notes:
Use Playwright's page.evaluate() to check localStorage values.

Test structure:
```typescript
test.describe('Signup Flow', () => {
  test('renders signup form correctly', async ({ page }) => {
    await page.goto('/signup');
    await expect(page.getByLabel('Email')).toBeVisible();
    await expect(page.getByLabel('Display Name')).toBeVisible();
    await expect(page.getByRole('checkbox')).toBeChecked();
  });

  test('stores migration preference in localStorage', async ({ page }) => {
    await page.goto('/signup');
    await page.fill('[name=email]', 'test@example.com');
    await page.fill('[name=displayName]', 'TestUser');
    await page.click('button[type=submit]');
    const stored = await page.evaluate(() => localStorage.getItem('songscript_migrate_on_signup'));
    expect(stored).toBe('true');
  });
});
```
